137→        newElement.classList.add(
138→          'mr-2',
139→          'h-4',
140→          'w-4',
141→          'rounded',
142→          'border',
143→          'border-zinc-600',
144→          'bg-zinc-800',
145→          'appearance-none',
146→          'align-middle',
