 21→  toolStatus = 'pending',
 22→  timestamp,
 23→}: Props = $props();
 24→
 25→let isExpanded = $state(false);
 26→let showFullOutput = $state(false);
 27→
 28→// Threshold for truncating large outputs (characters)
 29→const OUTPUT_TRUNCATE_THRESHOLD = 1000;
 30→
 31→function toggleExpanded() {
 32→  isExpanded = !isExpanded;
 33→}
 34→
 35→function toggleShowFullOutput() {
 36→  showFullOutput = !showFullOutput;
 37→}
 38→
 39→// Format JSON for display
 40→function formatJson(data: unknown): string {
 41→  if (data === undefined || data === null) return '';
 42→  try {
 43→    if (typeof data === 'string') return data;
 44→    return JSON.stringify(data, null, 2);
 45→  } catch {
 46→    return String(data);
 47→  }
 48→}
 49→
 50→// Get a useful preview of tool input
 51→function getPreview(data: unknown): string {
 52→  if (data === undefined || data === null) return '';
 53→
 54→  // For strings, show truncated version
 55→  if (typeof data === 'string') {
 56→    if (data.length <= 60) return data;
 57→    return `${data.slice(0, 60)}...`;
 58→  }
 59→
 60→  // For objects, try to extract useful summary
 61→  if (typeof data === 'object') {
 62→    const obj = data as Record<string, unknown>;
 63→
 64→    // Common tool input patterns
 65→    if (typeof obj.command === 'string') {
 66→      return obj.command.length <= 60 ? obj.command : `${obj.command.slice(0, 60)}...`;
 67→    }
 68→    if (typeof obj.file_path === 'string') {
 69→      return obj.file_path;
 70→    }
 71→    if (typeof obj.pattern === 'string') {
 72→      return `pattern: ${obj.pattern}`;
 73→    }
 74→    if (typeof obj.query === 'string') {
 75→      return obj.query.length <= 60 ? obj.query : `${obj.query.slice(0, 60)}...`;
 76→    }
 77→
 78→    // Show key count for complex objects
 79→    const keys = Object.keys(obj);
 80→    if (keys.length <= 3) {
 81→      return keys.join(', ');
 82→    }
 83→    return `${keys.length} properties`;
 84→  }
 85→
 86→  return String(data);
 87→}
