126→  toolStatus === 'failed'
127→    ? 'bg-red-950/50'
128→    : toolStatus === 'cancelled'
129→      ? 'bg-amber-950/50'
130→      : toolStatus === 'completed'
131→        ? 'bg-emerald-950/50'
132→        : 'bg-blue-950/50',
133→);
134→</script>
