// =============================================================================
// Session Update Event Helpers
// =============================================================================

/**
 * Raw ACP SessionUpdate structure from the Hub via sessions:updates topic.
 */
export interface AcpSessionUpdate {
  sessionUpdate: string;
  content?: { type: string; text?: string };
  toolCallId?: string;
  name?: string;
  title?: string;
  rawInput?: unknown;
  rawOutput?: unknown;
  status?: 'pending' | 'in_progress' | 'completed' | 'failed' | null;
  _meta?: Record<string, unknown>;
  [key: string]: unknown;
}

/**
 * Session update event data from sessions:updates topic.
 */
export interface SessionUpdateEventData {
  sessionId: string;
  update: AcpSessionUpdate;
  timestamp: number;
}

/**
 * Check if a sessions:updates event is a session event update (vs status/watermark update).
 */
export function isSessionEventUpdate(data: unknown): data is SessionUpdateEventData {
  return (
    typeof data === 'object' &&
    data !== null &&
    'sessionId' in data &&
    'update' in data &&
    typeof (data as SessionUpdateEventData).update === 'object' &&
    (data as SessionUpdateEventData).update !== null &&
    'sessionUpdate' in (data as SessionUpdateEventData).update
  );
}

