/**
 * WebSocket Manager for Hub UI
 *
 * Handles WebSocket connection to Hub with:
 * - Automatic reconnection with exponential backoff
 * - Topic subscription management
 * - Message routing to handlers
 * - Ping/pong heartbeat handling
 */

import type { CommandAck, HubCommand, HubEvent, PingEventData } from './types.js';
import { TOPIC_SYSTEM } from './types.js';

// =============================================================================
// Types
// =============================================================================

export type ConnectionState = 'disconnected' | 'connecting' | 'connected' | 'reconnecting';

export type EventHandler<T = unknown> = (event: HubEvent<T>) => void;
export type StateChangeHandler = (state: ConnectionState) => void;
export type ErrorHandler = (error: Error) => void;

interface PendingRequest {
  resolve: (value: CommandAck) => void;
  reject: (error: Error) => void;
  timeout: ReturnType<typeof setTimeout>;
}

// =============================================================================
// WebSocket Manager
// =============================================================================

/**
 * WebSocket manager with reconnection and topic subscription.
 */
export class WebSocketManager {
  private ws: WebSocket | null = null;
  private url: string;
  private reconnectAttempts = 0;
  private maxReconnectAttempts = 10;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private requestCounter = 0;

  // Subscriptions and handlers
  private subscriptions = new Set<string>();
  private topicHandlers = new Map<string, Set<EventHandler>>();
  private stateChangeHandlers = new Set<StateChangeHandler>();
  private errorHandlers = new Set<ErrorHandler>();
  private pendingRequests = new Map<string, PendingRequest>();

  // State
  private _state: ConnectionState = 'disconnected';
  private _lastSeq = 0;

  constructor(url = 'ws://localhost:8766/ws/ui') {
    this.url = url;
  }

  // =============================================================================
  // Public API
  // =============================================================================

  /**
   * Get current connection state.
   */
  get state(): ConnectionState {
    return this._state;
  }

  /**
   * Get last received sequence number.
   */
  get lastSeq(): number {
    return this._lastSeq;
  }

  /**
   * Check if connected.
   */
  get isConnected(): boolean {
    return this._state === 'connected';
  }

  /**
   * Configure the WebSocket URL.
   */
  setUrl(url: string): void {
    this.url = url;
  }

  /**
   * Connect to the WebSocket server.
   */
  connect(): void {
    if (this.ws && (this._state === 'connected' || this._state === 'connecting')) {
      return;
    }

    this.setState(this.reconnectAttempts > 0 ? 'reconnecting' : 'connecting');

    try {
      this.ws = new WebSocket(this.url);
      this.ws.onopen = () => this.handleOpen();
      this.ws.onmessage = (e) => this.handleMessage(e);
      this.ws.onclose = (e) => this.handleClose(e);
      this.ws.onerror = (e) => this.handleError(e);
    } catch (error) {
      this.emitError(error instanceof Error ? error : new Error(String(error)));
      this.scheduleReconnect();
    }
  }

  /**
   * Disconnect from the WebSocket server.
   */
  disconnect(): void {
    this.clearReconnectTimer();
    this.reconnectAttempts = 0;

    if (this.ws) {
      this.ws.onclose = null; // Prevent reconnection
      this.ws.close(1000, 'Client disconnect');
      this.ws = null;
    }

    this.setState('disconnected');
  }

  /**
   * Subscribe to topics.
   * Returns a promise that resolves when the subscription is acknowledged.
   */
  async subscribe(topics: string[]): Promise<CommandAck> {
    const newTopics = topics.filter((t) => !this.subscriptions.has(t));
    if (newTopics.length === 0) {
      return { ack: true, action: 'subscribe', success: true };
    }

    // Track subscriptions locally
    for (const t of newTopics) {
      this.subscriptions.add(t);
    }

    // Send command if connected
    if (this.isConnected) {
      return this.sendCommand({ action: 'subscribe', topics: newTopics });
    }

    // Will be sent on reconnect
    return { ack: true, action: 'subscribe', success: true };
  }

  /**
   * Unsubscribe from topics.
   */
  async unsubscribe(topics: string[]): Promise<CommandAck> {
    const existingTopics = topics.filter((t) => this.subscriptions.has(t));
    if (existingTopics.length === 0) {
      return { ack: true, action: 'unsubscribe', success: true };
    }

    // Remove from local tracking
    for (const t of existingTopics) {
      this.subscriptions.delete(t);
    }

    // Send command if connected
    if (this.isConnected) {
      return this.sendCommand({ action: 'unsubscribe', topics: existingTopics });
    }

    return { ack: true, action: 'unsubscribe', success: true };
  }

  /**
   * Send a message to a session.
   */
  async sendSessionMessage(sessionId: string, content: string): Promise<CommandAck> {
    if (!this.isConnected) {
      throw new Error('Not connected');
    }
    return this.sendCommand({
      action: 'session.message',
      session_id: sessionId,
      payload: { content },
    });
  }

  /**
   * Send an interaction response.
   */
  async sendInteractionResponse(
    sessionId: string,
    interactionId: string,
    response: unknown,
  ): Promise<CommandAck> {
    if (!this.isConnected) {
      throw new Error('Not connected');
    }
    return this.sendCommand({
      action: 'session.interaction_response',
      session_id: sessionId,
      payload: { interaction_id: interactionId, response },
    });
  }

  /**
   * Register a handler for events on a topic.
   * Returns an unsubscribe function.
   */
  onTopic<T = unknown>(topic: string, handler: EventHandler<T>): () => void {
    if (!this.topicHandlers.has(topic)) {
      this.topicHandlers.set(topic, new Set());
    }
    this.topicHandlers.get(topic)?.add(handler as EventHandler);

    return () => {
      const handlers = this.topicHandlers.get(topic);
      if (handlers) {
        handlers.delete(handler as EventHandler);
        if (handlers.size === 0) {
          this.topicHandlers.delete(topic);
        }
      }
    };
  }

  /**
   * Register a connection state change handler.
   * Returns an unsubscribe function.
   */
  onStateChange(handler: StateChangeHandler): () => void {
    this.stateChangeHandlers.add(handler);
    return () => this.stateChangeHandlers.delete(handler);
  }

  /**
   * Register an error handler.
   * Returns an unsubscribe function.
   */
  onError(handler: ErrorHandler): () => void {
    this.errorHandlers.add(handler);
    return () => this.errorHandlers.delete(handler);
  }

  // =============================================================================
  // Internal Handlers
  // =============================================================================

  private handleOpen(): void {
    this.reconnectAttempts = 0;
    this.setState('connected');

    // Re-subscribe to all topics
    if (this.subscriptions.size > 0) {
      this.sendCommand({
        action: 'subscribe',
        topics: [...this.subscriptions],
      }).catch((err) => {
        this.emitError(new Error(`Failed to resubscribe: ${err.message}`));
      });
    }
  }

  private handleMessage(event: MessageEvent): void {
    try {
      const msg = JSON.parse(event.data as string);

      // Handle command acknowledgments
      if (msg.ack) {
        this.handleAck(msg as CommandAck);
        return;
      }

      // Handle events
      const hubEvent = msg as HubEvent;
      this._lastSeq = hubEvent.seq;

      // Handle pings
      if (hubEvent.topic === TOPIC_SYSTEM && hubEvent.event === 'ping') {
        const pingData = hubEvent.data as PingEventData;
        this.send({ action: 'pong', ping_timestamp: pingData.timestamp });
        return;
      }

      // Dispatch to topic handlers
      const handlers = this.topicHandlers.get(hubEvent.topic);
      if (handlers) {
        for (const handler of handlers) {
          try {
            handler(hubEvent);
          } catch (err) {
            console.error('Error in event handler:', err);
          }
        }
      }
    } catch (err) {
      this.emitError(new Error(`Failed to parse message: ${err}`));
    }
  }

  private handleClose(event: CloseEvent): void {
    this.ws = null;

    // Reject all pending requests
    for (const pending of this.pendingRequests.values()) {
      clearTimeout(pending.timeout);
      pending.reject(new Error(`Connection closed: ${event.code}`));
    }
    this.pendingRequests.clear();

    // Don't reconnect for clean closes
    if (event.code === 1000) {
      this.setState('disconnected');
      return;
    }

    // Schedule reconnection
    this.scheduleReconnect();
  }

  private handleError(_event: Event): void {
    // WebSocket error event doesn't provide useful info
    // The close event will follow with more details
  }

  private handleAck(ack: CommandAck): void {
    if (!ack.request_id) return;

    const pending = this.pendingRequests.get(ack.request_id);
    if (pending) {
      clearTimeout(pending.timeout);
      this.pendingRequests.delete(ack.request_id);
      pending.resolve(ack);
    }
  }

  // =============================================================================
  // Helpers
  // =============================================================================

  private send(command: HubCommand): void {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify(command));
    }
  }

  private sendCommand(command: HubCommand): Promise<CommandAck> {
    return new Promise((resolve, reject) => {
      const requestId = `req_${++this.requestCounter}`;
      const commandWithId = { ...command, request_id: requestId };

      const timeout = setTimeout(() => {
        this.pendingRequests.delete(requestId);
        reject(new Error('Command timeout'));
      }, 10000);

      this.pendingRequests.set(requestId, { resolve, reject, timeout });
      this.send(commandWithId);
    });
  }

  private setState(state: ConnectionState): void {
    if (this._state !== state) {
      this._state = state;
      for (const handler of this.stateChangeHandlers) {
        handler(state);
      }
    }
  }

  private emitError(error: Error): void {
    for (const handler of this.errorHandlers) {
      handler(error);
    }
  }

  private scheduleReconnect(): void {
    this.clearReconnectTimer();

    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
      this.setState('disconnected');
      this.emitError(new Error('Max reconnection attempts reached'));
      return;
    }

    this.setState('reconnecting');

    // Exponential backoff: 1s, 2s, 4s, 8s, ... up to 30s
    const delay = Math.min(1000 * 2 ** this.reconnectAttempts, 30000);
    this.reconnectAttempts++;

    this.reconnectTimer = setTimeout(() => {
      this.connect();
    }, delay);
  }

  private clearReconnectTimer(): void {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
  }
}

// =============================================================================
// Singleton Instance
// =============================================================================

/**
 * Default WebSocket manager instance.
 * Use this for the main Hub connection.
 */
export const wsManager = new WebSocketManager();

