    25→  createdAt: string;
    26→  /** Callback when user sends a message */
    27→  onSendMessage: (content: string) => void;
    28→  /** Whether the input is enabled */
    29→  canSendMessages?: boolean;
    30→  /** Callback to retry a failed optimistic message */
    31→  onRetryMessage?: (tempId: string) => void;
    32→  /** Callback to dismiss a failed optimistic message */
    33→  onDismissMessage?: (tempId: string) => void;
    34→}
    35→
    36→const {
    37→  sessionId,
    38→  messages,
    39→  createdAt,
    40→  onSendMessage,
    41→  canSendMessages = true,
    42→  onRetryMessage,
    43→  onDismissMessage,
    44→}: Props = $props();
    45→
    46→let messagesContainer: HTMLDivElement;
    47→let shouldAutoScroll = $state(true);
    48→let scrollRafId: number | null = null;
    49→let userScrolling = $state(false);
    50→let scrollTimeout: ReturnType<typeof setTimeout> | null = null;
    51→let newContentCount = $state(0);
    52→let lastMessageCount = $state(0);
    53→
    54→// Check prefers-reduced-motion once on mount
    55→let prefersReducedMotion = $state(false);
    56→
    57→// Check if agent is currently "thinking" - last message is from user without agent response
    58→const isThinking = $derived(() => {
    59→  if (messages.length === 0) return false;
    60→  const lastMessage = messages[messages.length - 1];
    61→  return lastMessage.type === 'user_message';
    62→});
    63→
    64→// Check if any message is currently streaming
    65→const isStreaming = $derived(() => {
    66→  return messages.some((m) => m.is_streaming);
    67→});
    68→
    69→// Show jump button when scrolled up and content is streaming
    70→const showJumpButton = $derived(() => !shouldAutoScroll && isStreaming());
    71→
    72→// Calculate session duration
    73→const sessionDuration = $derived(() => {
    74→  const start = new Date(createdAt);
    75→  const now = new Date();
    76→  const diffMs = now.getTime() - start.getTime();
    77→  const diffMins = Math.floor(diffMs / 60000);
    78→  const diffSecs = Math.floor((diffMs % 60000) / 1000);
    79→  return `${diffMins}m ${diffSecs}s`;
    80→});
    81→
    82→// Filter out empty messages (messages with no content except tool_call which has no content field)
    83→const filteredMessages = $derived(
    84→  messages.filter((m) => {
    85→    // Tool calls always shown (they have input/output, not content)
    86→    if (m.type === 'tool_call') return true;
    87→    // Text-based messages need content
    88→    const content = (m as { content?: string }).content;
    89→    return content && content.trim().length > 0;
    90→  }),
    91→);
    92→
    93→// Debounced smooth scroll to bottom using requestAnimationFrame
    94→function scrollToBottom() {
    95→  if (scrollRafId !== null) {
    96→    cancelAnimationFrame(scrollRafId);
    97→  }
    98→  scrollRafId = requestAnimationFrame(() => {
    99→    scrollRafId = null;
   100→    if (messagesContainer) {
   101→      messagesContainer.scrollTo({
   102→        top: messagesContainer.scrollHeight,
   103→        behavior: prefersReducedMotion ? 'auto' : 'smooth',
   104→      });
   105→    }
   106→  });
   107→}
   108→
   109→// Jump to bottom and re-enable auto-scroll
   110→function jumpToBottom() {
   111→  shouldAutoScroll = true;
   112→  newContentCount = 0;
   113→  scrollToBottom();
   114→}
   115→
   116→// Auto-scroll to bottom when new messages arrive or content changes
   117→$effect(() => {
   118→  // Track filtered messages to detect changes (length and last message content)
   119→  const lastMsg = filteredMessages[filteredMessages.length - 1];
   120→  const _ =
   121→    lastMsg?.type === 'agent_message' || lastMsg?.type === 'agent_thought'
   122→      ? (lastMsg as { content?: string }).content?.length
   123→      : filteredMessages.length;
   124→
   125→  // Skip auto-scroll if user is actively scrolling
   126→  if (shouldAutoScroll && !userScrolling && messagesContainer) {
   127→    tick().then(scrollToBottom);
   128→  }
   129→});
   130→
   131→// Track new content arriving while scrolled up
   132→$effect(() => {
   133→  const currentCount = filteredMessages.length;
   134→  if (!shouldAutoScroll && currentCount > lastMessageCount) {
   135→    newContentCount += currentCount - lastMessageCount;
   136→  }
   137→  lastMessageCount = currentCount;
   138→});
   139→
   140→// Detect when user scrolls away from bottom
   141→function handleScroll() {
   142→  if (!messagesContainer) return;
   143→
   144→  // Mark user as actively scrolling
   145→  userScrolling = true;
   146→  if (scrollTimeout) clearTimeout(scrollTimeout);
   147→  scrollTimeout = setTimeout(() => {
   148→    userScrolling = false;
   149→  }, 150);
   150→
   151→  const { scrollTop, scrollHeight, clientHeight } = messagesContainer;
   152→  const totalScrollable = scrollHeight - clientHeight;
   153→  const distanceFromBottom = scrollHeight - scrollTop - clientHeight;
   154→
   155→  // Smart threshold: if content barely scrolls, use tight threshold to avoid jumpy behavior
   156→  // Otherwise use forgiving 100px threshold
   157→  if (totalScrollable < 100) {
   158→    // Tight threshold for short content - only snap at exact bottom
   159→    shouldAutoScroll = distanceFromBottom < 5;
   160→  } else {
   161→    // Forgiving threshold for longer content
   162→    shouldAutoScroll = distanceFromBottom < 100;
   163→  }
   164→
   165→  // Reset new content count when user scrolls back to bottom
   166→  if (shouldAutoScroll) {
   167→    newContentCount = 0;
   168→  }
   169→}
   170→
   171→onMount(() => {
   172→  // Check prefers-reduced-motion
   173→  prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
   174→
   175→  // Initialize lastMessageCount
   176→  lastMessageCount = filteredMessages.length;
   177→
   178→  // Scroll to bottom initially (instant, not smooth for initial load)
   179→  if (messagesContainer) {
   180→    messagesContainer.scrollTop = messagesContainer.scrollHeight;
   181→  }
   182→
   183→  // Cleanup on unmount
   184→  return () => {
   185→    if (scrollRafId !== null) {
   186→      cancelAnimationFrame(scrollRafId);
   187→    }
   188→    if (scrollTimeout) {
   189→      clearTimeout(scrollTimeout);
   190→    }
   191→  };
   192→});
   193→</script>
   194→
   195→<div class="flex min-h-0 flex-1 flex-col overflow-hidden">
   196→	<!-- Messages container with jump button -->
   197→	<div class="relative min-h-0 flex-1">
   198→		<div
   199→			bind:this={messagesContainer}
   200→			onscroll={handleScroll}
   201→			class="absolute inset-0 space-y-3 overflow-y-auto px-4 py-3"
   202→		>
   203→			{#if filteredMessages.length === 0}
   204→				<div class="flex h-full items-center justify-center">
   205→					<p class="text-sm text-zinc-600">No messages yet</p>
   206→				</div>
   207→			{:else}
   208→				{#each filteredMessages as message (message.id)}
   209→					<ErrorBoundary name="Message" message="Failed to render message">
   210→						{#snippet children()}
   211→							<ChatMessage
   212→								{message}
   213→								onRetry={message.tempId && onRetryMessage ? () => onRetryMessage(message.tempId!) : undefined}
   214→								onDismiss={message.tempId && onDismissMessage ? () => onDismissMessage(message.tempId!) : undefined}
   215→							/>
   216→						{/snippet}
   217→					</ErrorBoundary>
   218→				{/each}
   219→
   220→				{#if isThinking()}
   221→					<ThinkingIndicator />
   222→				{/if}
   223→			{/if}
   224→		</div>
   225→
   226→		<!-- Jump to Bottom button -->
   227→		{#if showJumpButton()}
   228→			<button
   229→				onclick={jumpToBottom}
   230→				class="absolute bottom-4 right-6 flex items-center gap-1.5 rounded-full bg-zinc-800 px-3 py-1.5 text-xs font-medium text-zinc-200 shadow-lg transition-all hover:bg-zinc-700 hover:shadow-xl"
   231→				aria-label="Jump to bottom"
   232→			>
   233→				<ChevronDown class="h-3.5 w-3.5" />
   234→				{#if newContentCount > 0}
   235→					<span class="rounded-full bg-blue-500 px-1.5 py-0.5 text-[10px] font-bold text-white">
   236→						{newContentCount > 99 ? '99+' : newContentCount}
   237→					</span>
   238→				{:else}
   239→					<span>Jump to bottom</span>
   240→				{/if}
   241→			</button>
   242→		{/if}
   243→	</div>
   244→
   245→	<!-- Input area -->
   246→	<ChatInput
   247→		{sessionId}
   248→		onSend={onSendMessage}
   249→		disabled={!canSendMessages}
   250→		sessionDuration={sessionDuration()}
   251→	/>
   252→</div>
   253→
