/**
 * Aggregated Message Types for UI Display
 *
 * This is the canonical format for both REST and WebSocket message delivery.
 * Multiple streaming events are aggregated into coherent UI messages.
 *
 * @see specs/STREAMING_MESSAGE_AGGREGATION.md
 * @see kynetic-r0i5 - Phase 1: Core aggregation types and streaming store
 */

// =============================================================================
// Aggregated Message Types
// =============================================================================

/**
 * Aggregated message for UI display.
 * This is the canonical format for both REST and WebSocket.
 */
export type AggregatedMessage = UserMessage | AgentMessage | AgentThought | ToolCall;

/**
 * Base interface for all aggregated messages.
 */
export interface BaseAggregatedMessage {
  /** Stable ID for this logical message (format: {session_id}-t{turn}-b{block}) */
  id: string;
  /** When message started */
  started_at: string;
  /** Last update time */
  updated_at: string;
  /** True while still receiving content */
  is_streaming: boolean;
}

/**
 * User message - input from the user.
 */
export interface UserMessage extends BaseAggregatedMessage {
  type: 'user_message';
  content: string;
}

/**
 * Agent message - text output from the agent.
 */
export interface AgentMessage extends BaseAggregatedMessage {
  type: 'agent_message';
  content: string;
}

/**
 * Agent thought - thinking/reasoning content.
 */
export interface AgentThought extends BaseAggregatedMessage {
  type: 'agent_thought';
  content: string;
}

/**
 * Tool call status.
 */
export type ToolCallStatus = 'pending' | 'running' | 'completed' | 'failed' | 'cancelled';

/**
 * Tool call - a tool invocation with lifecycle tracking.
 */
export interface ToolCall extends BaseAggregatedMessage {
  type: 'tool_call';
  /** Unique identifier for tool call correlation */
  tool_call_id: string;
  /** Tool name (e.g., "Read", "Edit", "Bash") */
  tool: string;
  /** Display-friendly summary (e.g., file path, search query) */
  summary?: string;
  /** Tool-specific input */
  input: unknown;
  /** Tool output (populated on completion) */
  output?: unknown;
  /** Current status in lifecycle */
  status: ToolCallStatus;
  /** Present when status is 'completed', 'failed', or 'cancelled' */
  completed_at?: string;
}

// =============================================================================
// Session Metadata Types
// =============================================================================

/**
 * Plan entry in an agent's plan.
 */
export interface PlanEntry {
  /** Plan step ID */
  id: string;
  /** Step description */
  content: string;
  /** Completion status */
  completed: boolean;
}

/**
 * Command available in the session.
 */
export interface Command {
  /** Command name (e.g., "/help", "/clear") */
  name: string;
  /** Command description */
  description?: string;
}

/**
 * Session metadata that doesn't affect the transcript.
 * Updated via meta events (plan, mode, commands).
 */
export interface SessionMeta {
  /** Current agent plan (replaced on each update) */
  plan: PlanEntry[] | null;
  /** Current interaction mode ID */
  currentModeId: string | null;
  /** Available slash commands */
  availableCommands: Command[] | null;
}

// =============================================================================
// Aggregation State Types
// =============================================================================

/**
 * Full aggregation state for a session.
 */
export interface AggregationState {
  /** Session ID */
  sessionId: string;
  /** Aggregated messages array */
  messages: AggregatedMessage[];
  /** O(1) lookup by message ID */
  messageById: Map<string, AggregatedMessage>;
  /** Last processed sequence number for deduplication */
  lastSeqProcessed: number;
  /** Current turn index (starts at -1, first event increments to 0) */
  turnIndex: number;
  /** Current block index within turn (starts at 0, resets on new turn) */
  blockIndex: number;
  /** Last role seen (null initially) */
  lastRole: 'user' | 'agent' | null;
  /** ID of currently streaming message (text/thought only, NOT tool_call) */
  activeMessageId: string | null;
  /** Pending tool calls: tool_call_id -> message.id */
  pendingTools: Map<string, string>;
  /** Session metadata (not part of transcript) */
  sessionMeta: SessionMeta;
}

// =============================================================================
// Type Guards
// =============================================================================

/**
 * Check if a value is a UserMessage.
 */
export function isUserMessage(msg: unknown): msg is UserMessage {
  return (
    typeof msg === 'object' && msg !== null && (msg as { type?: unknown }).type === 'user_message'
  );
}

/**
 * Check if a value is an AgentMessage.
 */
export function isAgentMessage(msg: unknown): msg is AgentMessage {
  return (
    typeof msg === 'object' && msg !== null && (msg as { type?: unknown }).type === 'agent_message'
  );
}

/**
 * Check if a value is an AgentThought.
 */
export function isAgentThought(msg: unknown): msg is AgentThought {
  return (
    typeof msg === 'object' && msg !== null && (msg as { type?: unknown }).type === 'agent_thought'
  );
}

/**
 * Check if a value is a ToolCall.
 */
export function isToolCall(msg: unknown): msg is ToolCall {
  return (
    typeof msg === 'object' && msg !== null && (msg as { type?: unknown }).type === 'tool_call'
  );
}

/**
 * Check if a value is an AggregatedMessage.
 */
export function isAggregatedMessage(msg: unknown): msg is AggregatedMessage {
  return isUserMessage(msg) || isAgentMessage(msg) || isAgentThought(msg) || isToolCall(msg);
}

/**
 * Check if a tool call status is terminal.
 */
export function isTerminalToolStatus(
  status: ToolCallStatus,
): status is 'completed' | 'failed' | 'cancelled' {
  return status === 'completed' || status === 'failed' || status === 'cancelled';
}

// =============================================================================
// Role Helpers
// =============================================================================

/**
 * Get the role for a message type.
 */
export function roleForMessageType(messageType: AggregatedMessage['type']): 'user' | 'agent' {
  switch (messageType) {
    case 'user_message':
      return 'user';
    case 'agent_message':
    case 'agent_thought':
    case 'tool_call':
      return 'agent';
  }
}

// =============================================================================
// Factory Functions
// =============================================================================

/**
 * Create initial session metadata.
 */
export function createSessionMeta(): SessionMeta {
  return {
    plan: null,
    currentModeId: null,
    availableCommands: null,
  };
}

/**
 * Create initial aggregation state for a session.
 *
 * Per spec Section 4.1:
 * - turnIndex starts at -1 (first event increments to 0)
 * - blockIndex starts at 0
 * - lastRole starts at null
 * - lastSeqProcessed starts at -1
 */
export function createAggregationState(sessionId: string): AggregationState {
  return {
    sessionId,
    messages: [],
    messageById: new Map(),
    lastSeqProcessed: -1,
    turnIndex: -1,
    blockIndex: 0,
    lastRole: null,
    activeMessageId: null,
    pendingTools: new Map(),
    sessionMeta: createSessionMeta(),
  };
}

/**
 * Generate a message ID from aggregation state.
 *
 * Format: {sessionId}-t{turnIndex}-b{blockIndex}
 */
export function generateMessageId(state: AggregationState): string {
  return `${state.sessionId}-t${state.turnIndex}-b${state.blockIndex}`;
}

/**
 * Parse turn and block indices from a message ID.
 *
 * @returns [turnIndex, blockIndex] or null if parsing fails
 */
export function parseMessageId(id: string): [number, number] | null {
  const match = id.match(/-t(\d+)-b(\d+)$/);
  if (!match) {
    return null;
  }
  return [parseInt(match[1], 10), parseInt(match[2], 10)];
}

// =============================================================================
// Message Manager Event Types
// =============================================================================

/**
 * Events emitted by SessionMessageManager.
 * These provide a clean, semantic API for UI updates without requiring
 * complex client-side aggregation logic.
 *
 * @see kynetic-f8vf.5 - Simplify UI streaming-messages aggregation
 */
export type MessageManagerEvent =
  | { type: 'message_started'; sessionId: string; message: AggregatedMessage }
  | {
      type: 'message_chunk';
      sessionId: string;
      messageId: string;
      content: string;
      timestamp: string;
    }
  | { type: 'message_finalized'; sessionId: string; message: AggregatedMessage }
  | { type: 'tool_started'; sessionId: string; tool: ToolCall }
  | { type: 'tool_updated'; sessionId: string; tool: ToolCall }
  | { type: 'tool_completed'; sessionId: string; tool: ToolCall }
  | { type: 'turn_completed'; sessionId: string; turnIndex: number }
  | { type: 'meta_updated'; sessionId: string; meta: SessionMeta };

/**
 * Type guard for MessageManagerEvent.
 */
export function isMessageManagerEvent(event: unknown): event is MessageManagerEvent {
  if (typeof event !== 'object' || event === null) return false;
  const e = event as { type?: unknown; sessionId?: unknown };
  if (typeof e.type !== 'string' || typeof e.sessionId !== 'string') return false;
  return [
    'message_started',
    'message_chunk',
    'message_finalized',
    'tool_started',
    'tool_updated',
    'tool_completed',
    'turn_completed',
    'meta_updated',
  ].includes(e.type);
}

