/**
 * Syntax highlighting utility using highlight.js
 *
 * Uses a curated set of common languages to keep bundle size reasonable
 * while supporting auto-detection for unmarked code blocks.
 */
import hljs from 'highlight.js/lib/core';

// Import common languages
import bash from 'highlight.js/lib/languages/bash';
import c from 'highlight.js/lib/languages/c';
import cpp from 'highlight.js/lib/languages/cpp';
import css from 'highlight.js/lib/languages/css';
import diff from 'highlight.js/lib/languages/diff';
import go from 'highlight.js/lib/languages/go';
import java from 'highlight.js/lib/languages/java';
import javascript from 'highlight.js/lib/languages/javascript';
import json from 'highlight.js/lib/languages/json';
import markdown from 'highlight.js/lib/languages/markdown';
import python from 'highlight.js/lib/languages/python';
import rust from 'highlight.js/lib/languages/rust';
import sql from 'highlight.js/lib/languages/sql';
import typescript from 'highlight.js/lib/languages/typescript';
import xml from 'highlight.js/lib/languages/xml'; // includes HTML
import yaml from 'highlight.js/lib/languages/yaml';

// Register languages with their primary names
hljs.registerLanguage('bash', bash);
hljs.registerLanguage('c', c);
hljs.registerLanguage('cpp', cpp);
hljs.registerLanguage('css', css);
hljs.registerLanguage('diff', diff);
hljs.registerLanguage('go', go);
hljs.registerLanguage('java', java);
hljs.registerLanguage('javascript', javascript);
hljs.registerLanguage('json', json);
hljs.registerLanguage('markdown', markdown);
hljs.registerLanguage('python', python);
hljs.registerLanguage('rust', rust);
hljs.registerLanguage('sql', sql);
hljs.registerLanguage('typescript', typescript);
hljs.registerLanguage('xml', xml);
hljs.registerLanguage('yaml', yaml);

// Register common aliases
hljs.registerLanguage('sh', bash);
hljs.registerLanguage('shell', bash);
hljs.registerLanguage('zsh', bash);
hljs.registerLanguage('js', javascript);
hljs.registerLanguage('jsx', javascript);
hljs.registerLanguage('ts', typescript);
hljs.registerLanguage('tsx', typescript);
hljs.registerLanguage('py', python);
hljs.registerLanguage('html', xml);
hljs.registerLanguage('htm', xml);
hljs.registerLanguage('yml', yaml);
hljs.registerLanguage('md', markdown);
hljs.registerLanguage('c++', cpp);
hljs.registerLanguage('golang', go);
hljs.registerLanguage('rs', rust);
hljs.registerLanguage('patch', diff);

/**
 * Highlight code with syntax highlighting.
 *
 * @param code - The code string to highlight
 * @param language - Optional language hint (e.g., 'javascript', 'python')
 * @returns HTML string with syntax highlighting spans
 */
export function highlightCode(code: string, language?: string): string {
  // If language specified and registered, use it
  if (language) {
    const normalizedLang = language.toLowerCase();
    if (hljs.getLanguage(normalizedLang)) {
      try {
        return hljs.highlight(code, { language: normalizedLang }).value;
      } catch {
        // Fall through to auto-detection if highlighting fails
      }
    }
  }

  // Auto-detect among loaded languages
  try {
    const result = hljs.highlightAuto(code);
    return result.value;
  } catch {
    // Return escaped code if all else fails
    return escapeHtml(code);
  }
}

/**
 * Check if a language is supported for highlighting.
 */
export function isLanguageSupported(language: string): boolean {
  return hljs.getLanguage(language.toLowerCase()) !== undefined;
}

/**
 * Get list of supported language names.
 */
export function getSupportedLanguages(): string[] {
  return hljs.listLanguages();
}

/**
 * Escape HTML special characters.
 */
function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

