    79→      }
    80→    }
    81→  }
    82→
    83→  // Auto-detect among loaded languages
    84→  try {
    85→    const result = hljs.highlightAuto(code);
    86→    return result.value;
    87→  } catch {
    88→    // Return escaped code if all else fails
    89→    return escapeHtml(code);
    90→  }
    91→}
    92→
    93→/**
    94→ * Check if a language is supported for highlighting.
    95→ */
    96→export function isLanguageSupported(language: string): boolean {
    97→  return hljs.getLanguage(language.toLowerCase()) !== undefined;
    98→}
    99→
   100→/**
   101→ * Get list of supported language names.
   102→ */
   103→export function getSupportedLanguages(): string[] {
   104→  return hljs.listLanguages();
   105→}
   106→
   107→/**
   108→ * Escape HTML special characters.
   109→ */
   110→function escapeHtml(text: string): string {
   111→  return text
   112→    .replace(/&/g, '&amp;')
   113→    .replace(/</g, '&lt;')
   114→    .replace(/>/g, '&gt;')
   115→    .replace(/"/g, '&quot;')
   116→    .replace(/'/g, '&#039;');
   117→}
