/**
 * Lazy-loaded Mermaid diagram renderer.
 *
 * Mermaid is loaded on-demand to minimize initial bundle size.
 * The library is only fetched when a mermaid code block is detected.
 */

let mermaidPromise: Promise<typeof import('mermaid')> | null = null;

/**
 * Lazy-load the mermaid library.
 * Returns a cached promise if already loading/loaded.
 */
export async function loadMermaid() {
  if (!mermaidPromise) {
    mermaidPromise = import('mermaid').then((m) => {
      m.default.initialize({
        startOnLoad: false,
        theme: 'dark',
        securityLevel: 'strict',
        // Suppress console logs from mermaid
        logLevel: 'error' as const,
      });
      return m;
    });
  }
  return mermaidPromise;
}

/** Counter for unique diagram IDs */
let diagramCounter = 0;

/**
 * Render a mermaid diagram into an element.
 *
 * @param element - The container element to render into
 * @param code - The mermaid diagram code
 * @throws Error if rendering fails (invalid syntax, etc.)
 */
export async function renderMermaid(element: HTMLElement, code: string): Promise<void> {
  const mermaid = await loadMermaid();

  // Generate unique ID for this diagram
  const id = `mermaid-${Date.now()}-${diagramCounter++}`;

  const { svg } = await mermaid.default.render(id, code);
  element.innerHTML = svg;
}

/**
 * Check if a language identifier indicates a mermaid diagram.
 */
export function isMermaidLanguage(language: string | undefined): boolean {
  return language?.toLowerCase() === 'mermaid';
}

