 */
export async function closeSession(
  specDir: string,
  sessionId: string,
  status: SessionStatus,
  reason: string,
): Promise<SessionMetadata | null> {
  const metadata = await getSession(specDir, sessionId);
  if (!metadata) {
    return null;
