import {
  compactSessionEvents,
  createSession,
  getSessionDir,
  getSessionEventsPath,
  updateSessionStatus,
} from "../src/sessions/store.js";
import {
  cleanupTempDir,
  kspec,
  kspecJson,
  setupTempFixtures,
  testUlid,
} from "./helpers/cli.js";

interface SessionCompactJson {
  dry_run: boolean;
  all: boolean;
  session?: {
    session_id: string;
    status: string;
    changed: boolean;
    events_processed: number;
    blobs_created: number;
    bytes_before: number;
    bytes_after: number;
    bytes_reclaimed: number;
  };
  sessions?: Array<{
    session_id: string;
    status: string;
  }>;
  totals: {
    sessions_total: number;
    sessions_processed: number;
    sessions_changed: number;
    sessions_skipped_active: number;
    sessions_failed: number;
    events_processed: number;
    blobs_created: number;
    bytes_before: number;
    bytes_after: number;
    bytes_reclaimed: number;
  };
}

describe("session compact", () => {
  let tempDir: string;

  beforeEach(async () => {
    tempDir = await setupTempFixtures();
  });

  afterEach(async () => {
    await cleanupTempDir(tempDir);
  });

