  ): Promise<void> {
    const eventsPath = getSessionEventsPath(tempDir, sessionId);
    const event = {
      ts: 1000,
      seq: 0,
      type: "session.update",
      session_id: sessionId,
      data: {
        iteration: 1,
        update: {
          sessionUpdate: "tool_call_update",
