    expect(pointer.path).toMatch(/^blobs\//);

    const blobPath = path.join(getSessionDir(tempDir, sessionId), pointer.path);
    const blobContent = await fs.readFile(blobPath, "utf-8");
    expect(blobContent).toBe(rawOutput);
  });

