      expect(text).toBe("existing");
      text = accumulateStreamingText(text, { event: "agent_text_chunk", data: { session_id: "s1" } }, "s1");
      expect(text).toBe("existing");
    });

    // AC: @ui-session-stream ac-2
    it("handles null data gracefully", () => {
