        { ts: 5000, seq: 50, type: "session.update", session_id: "s1", data: { update: { sessionUpdate: "assistant_text", text: "partial text from chunks" } } },
      ];
      const blocks = parseEventsToBlocks(newEvents);
      expect(blocks.length).toBeGreaterThan(0);
